.item-icon image{width:100%;height:100%}
.item-icon text{position:absolute;right:4px;bottom:3px;color:white;font-size:16px;text-shadow:0 1px 2px #685127}
.remaining{font-size:11px;color:#849177;margin:7px 0}
.price{height:30px;line-height:30px;border-radius:22px;background:linear-gradient(90deg,#ee9d2d,#f5c04d);color:white;font-size:12px;font-weight:600}
